import{_ as e,o,c as a,a2 as r}from"./chunks/framework.CFOYCmPM.js";const i="/dayz-studio/manual/images/dayz_studio_map_view.png",h=JSON.parse('{"title":"Chapter 2: Interface Tour & Navigation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/interface-tour.md","filePath":"guide/interface-tour.md","lastUpdated":null}'),n={name:"guide/interface-tour.md"};function s(l,t,d,c,g,u){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="chapter-2-interface-tour-navigation" tabindex="-1">Chapter 2: Interface Tour &amp; Navigation <a class="header-anchor" href="#chapter-2-interface-tour-navigation" aria-label="Permalink to &quot;Chapter 2: Interface Tour &amp; Navigation&quot;">​</a></h1><p>DayZ Studio provides an integrated workspace designed for fast, frictionless mod creation. Let&#39;s explore the core layout and navigation tools.</p><hr><h2 id="🖥️-anatomy-of-the-workspace" tabindex="-1">🖥️ Anatomy of the Workspace <a class="header-anchor" href="#🖥️-anatomy-of-the-workspace" aria-label="Permalink to &quot;🖥️ Anatomy of the Workspace&quot;">​</a></h2><p><img src="'+i+'" alt="DayZ Studio 2D Map View &amp; Layout"></p><p>The interface is divided into four main regions:</p><ol><li><p><strong>Top Navigation Bar:</strong></p><ul><li><strong>File ▾ Menu:</strong> Create, open, or save projects, and load pre-built templates (such as the Showcase camp).</li><li><strong>Undo / Redo (<code>Ctrl+Z</code> / <code>Ctrl+Y</code>):</strong> Full state history for all prop placements, node edits, and deletions.</li><li><strong>View Switcher:</strong> One-click toggles between <strong>Map</strong>, <strong>Game</strong>, <strong>3D</strong>, <strong>Quests</strong>, and <strong>NPCs</strong>.</li><li><strong>Tool Selector:</strong> Choose between Select (<code>V</code>), Pan (<code>H</code>), and Measure (<code>M</code>).</li><li><strong>Grid Snapping (<code>G</code>):</strong> Cycles through <em>Off ➔ 1m ➔ 5m ➔ 10m ➔ 25m ➔ 50m</em>.</li><li><strong>Pre-Flight Checker (<code>✔ Check</code>):</strong> Scans your project for disconnected nodes, invalid classnames, or high object densities.</li><li><strong>Build Button (<code>⇩ Export</code>):</strong> Opens the 1-click mod packaging dialog.</li></ul></li><li><p><strong>Central Canvas:</strong></p><ul><li>Adapts to your active view (2D satellite map, 3D interactive scene, Quest Node Graph, or NPC Behaviour Canvas).</li></ul></li><li><p><strong>Inspector Panel (Right):</strong></p><ul><li>Context-sensitive sidebar. When you click an object, NPC, or quest node, this panel displays coordinates, rotations, dialogue lines, clothing, and loot settings.</li></ul></li><li><p><strong>Status Bar (Bottom):</strong></p><ul><li>Displays real-time cursor coordinates <code>(X, Z)</code>, current zoom percentage, total object count, and live DayZ engine connection status.</li></ul></li></ol><hr><h2 id="🔀-the-five-core-views-alt-1-to-alt-5" tabindex="-1">🔀 The Five Core Views (<code>Alt + 1</code> to <code>Alt + 5</code>) <a class="header-anchor" href="#🔀-the-five-core-views-alt-1-to-alt-5" aria-label="Permalink to &quot;🔀 The Five Core Views (`Alt + 1` to `Alt + 5`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">View</th><th style="text-align:left;">Hotkey</th><th style="text-align:left;">What You Do Here</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>🗺 Map</strong></td><td style="text-align:left;"><code>Alt + 1</code></td><td style="text-align:left;">High-res 2D tactical map. Plan outposts, draw loot zones, plot NPC patrol routes, and set quest triggers.</td></tr><tr><td style="text-align:left;"><strong>🎮 Game</strong></td><td style="text-align:left;"><code>Alt + 2</code></td><td style="text-align:left;">Embedded borderless DayZ client. Walk through your edits with live loot, roaming infected, and sub-second live sync.</td></tr><tr><td style="text-align:left;"><strong>🧊 3D Preview</strong></td><td style="text-align:left;"><code>Alt + 3</code></td><td style="text-align:left;">Fast 3D navigation. Precision placement, rotation gizmos, wall/roof surface snapping, and erasing vanilla objects.</td></tr><tr><td style="text-align:left;"><strong>⎇ Quests</strong></td><td style="text-align:left;"><code>Alt + 4</code></td><td style="text-align:left;">Skyrim-style visual dialogue trees, branching choices, objectives, and reward triggers.</td></tr><tr><td style="text-align:left;"><strong>👤 NPCs</strong></td><td style="text-align:left;"><code>Alt + 5</code></td><td style="text-align:left;">Character creator and autonomous behavior graphs (patrols, day/night schedules, emotes, traders).</td></tr></tbody></table><hr><h2 id="🖥️-multi-monitor-docking-support" tabindex="-1">🖥️ Multi-Monitor &amp; Docking Support <a class="header-anchor" href="#🖥️-multi-monitor-docking-support" aria-label="Permalink to &quot;🖥️ Multi-Monitor &amp; Docking Support&quot;">​</a></h2><p>DayZ Studio is fully modular:</p><ul><li><strong>Drag Tabs Anywhere:</strong> You can drag any view tab (even the live 3D preview or Game client!) completely <strong>out of the main window</strong> and drop it onto a second monitor.</li><li><strong>Side-by-Side Docking:</strong> Drag the <strong>Quests</strong> tab to the right half of the screen and the <strong>Map</strong> tab to the left half to design dialogue trees while tracking trigger coordinates simultaneously.</li><li><strong>Layout Presets (<code>Ctrl + Shift + W</code>):</strong> Quickly switch between <em>Default</em>, <em>Mapping</em>, <em>Quest Writing</em>, or save your own custom <code>.dzworkspace.json</code> profile.</li></ul>',14)])])}const m=e(n,[["render",s]]);export{h as __pageData,m as default};
